import { api } from '@/lib/api';export default async function Page(){const agents=await api.agents();return <><h1 className="text-3xl font-black">Agents</h1><p className="mb-6 text-slate-500">Support team members available for ticket assignment.</p><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{agents.map(a=><div className="card p-5" key={a.id}><div className="flex justify-between"><h2 className="text-lg font-bold">{a.name}</h2><span className="badge">{a.status}</span></div><p className="mt-2 text-sm text-slate-600">{a.email}</p><p className="mt-1 text-sm font-semibold">{a.department}</p><p className="mt-4 text-xs text-slate-400">Joined {new Date(a.created_at).toLocaleDateString()}</p></div>)}</div></>}
